   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_rsvp_part_r']['opc_liga']['fix_top'])) {
       $this->Fix_bar_top = ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_rsvp_part_r']['opc_liga']['fix_top'] == "S") ? true : false;
   }
   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_rsvp_part_r']['opc_liga']['fix_bot'])) {
       $this->Fix_bar_bottom = ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_rsvp_part_r']['opc_liga']['fix_bot'] == "S") ? true : false;
   }
   $this->Det_colspan = " colspan=3";
