       $lin_obj .= "     <input  type=\"text\" class='sc-js-input " . $this->css_scAppDivToolbarInput . "' id='grid_search_hospedagem_tipo_pessoa_val_" . $ind . "' name='val_grid_search_hospedagem_tipo_pessoa_" . $ind . "' value=\"" . NM_encode_input($val_cmp) . "\" size=1 alt=\"{datatype: 'text', maxLength: 1, allowedChars: '', lettersCase: '', autoTab: false, enterTab: false}\" style='display: none'>";
       $tmp_pos = (is_string($val_cmp)) ? strpos($val_cmp, "##@@") : false;
       if ($tmp_pos !== false) {
           $val_cmp = substr($val_cmp, ($tmp_pos + 4));
           $sAutocompValue = substr($sAutocompValue, ($tmp_pos + 4));
       }
       $lin_obj .= "     <input class='sc-js-input " . $this->css_scAppDivToolbarInput . "' type='text' id='id_ac_grid_hospedagem_tipo_pessoa" . $ind . "' name='val_grid_search_hospedagem_tipo_pessoa_autocomp" . $ind . "' size='1' value='" . NM_encode_input($sAutocompValue) . "' alt=\"{datatype: 'text', maxLength: 1, allowedChars: '', lettersCase: '', autoTab: false, enterTab: false}\">";
