   $nm_saida->saida("          placement: 'bottom-start',\r\n");
   $nm_saida->saida("          middleware: [FloatingUIDOM.flip(), FloatingUIDOM.shift(), FloatingUIDOM.size({\r\n");
   $nm_saida->saida("            apply({availableWidth, availableHeight, elements}) {\r\n");
   $nm_saida->saida("              Object.assign(elements.floating.style, {\r\n");
   $nm_saida->saida("                maxWidth: availableWidth + 'px',\r\n");
   $nm_saida->saida("                maxHeight: availableHeight + 'px',\r\n");
   $nm_saida->saida("                overflow: 'auto'\r\n");
   $nm_saida->saida("              });\r\n");
   $nm_saida->saida("            }\r\n");
   $nm_saida->saida("          })],\r\n");
